test('physical time hotspots retain exact long values and link to their logical operator', () => {
    const harness = createScriptHarness();
    harness.runScript('scripts/queryExplanationHighlighter.js');
    const h = harness.context.workbench.queryExplanationHighlighter;
    const executionProfile = profile();
    executionProfile.stages[0].metrics.elapsed.count = '9007199254740993';
    const plan = { type: 'Group', resultSizeActual: 1, executionProfile,
        plans: [{ type: 'StatementPattern', logicalPath: '0/1', resultSizeActual: 0 }] };
    const hotspot = h.getHotspot(plan, 'Telemetry');
    assert.equal(hotspot.metric, 'physicalElapsedNanos');
    assert.equal(hotspot.maximum, '9007199254740993');
    const target = harness.document.createElement('pre');
    target.appendChild(h.render(plan, { level: 'Telemetry', mode: 'hotspot' }).fragment);
    const physical = target.querySelector('.query-explanation-line--physical');
    assert.equal(physical.getAttribute('data-heat'), '1.000');
    const logical = target.querySelector('[data-logical-path="0/1"]');
    let scrolled = false;
    logical.scrollIntoView = () => { scrolled = true; };
    physical.dispatchEvent({ type: 'click' });
    assert.equal(scrolled, true);
    assert.equal(harness.document.activeElement, logical);
});

